<script lang="ts">
  import { onMount } from 'svelte';
  import strftime from 'strftime';
  import { api } from '../lib/api.svelte';
  import type { Entry } from '../lib/types/models';

  let { onEdit } = $props<{ onEdit: (id: number) => void }>();

  let entries = $state<Entry[]>([]);
  let hasMore = $state(false);
  let limit = 50;
  let search = $state('');
  let cursors = $state<number[]>([]);

  async function fetchEntries() {
    try {
      const cursor = cursors[cursors.length - 1];
      const params: any = { limit };
      if (search) params.q = search;
      if (cursor) {
        params.cursor_id = cursor;
      }

      const data = await api.get<{ entries: Entry[], has_more: boolean }>('/admin/api/entries', params);
      entries = data.entries || [];
      hasMore = data.has_more || false;
    } catch (e) {
      console.error(e);
    }
  }

  function onSearch() {
    cursors = [];
    fetchEntries();
  }

  onMount(fetchEntries);

  function goOlder() {
    if (hasMore && entries.length > 0) {
      const last = entries[entries.length - 1];
      cursors.push(last.id);
      fetchEntries();
    }
  }

  function goNewer() {
    if (cursors.length > 0) {
      cursors.pop();
      fetchEntries();
    }
  }

  function formatTime(iso: string) {
    if (!iso) return '-';
    return strftime('%Y-%m-%d %H:%M', new Date(iso));
  }
</script>

{#snippet statusBadge(entry: Entry)}
  <span class="status status-{entry.status}">{entry.status}</span>
{/snippet}

{#snippet time(iso: string, valid: boolean = true)}
  <time datetime={iso}>{valid && iso ? formatTime(iso) : '-'}</time>
{/snippet}

<div class="entry-list">
  <div class="header">
    <h2>エントリ一覧</h2>
    <div class="search-box">
      <input type="text" placeholder="検索..." bind:value={search} onkeydown={e => e.key === 'Enter' && onSearch()} />
      <button onclick={onSearch}>検索</button>
    </div>
    <div class="pagination">
      <button disabled={cursors.length === 0 || api.loading} onclick={goNewer}>新しい方へ</button>
      <button disabled={!hasMore || api.loading} onclick={goOlder}>古い方へ</button>
    </div>
  </div>

  <div class="table-container" class:is-loading={api.loading}>
    {#if api.loading && entries.length === 0}
      <div class="loading-spinner-container">
        <div class="loading-spinner"></div>
      </div>
    {:else}
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>日付</th>
            <th>ステータス</th>
            <th>タイトル / パス</th>
            <th>形式</th>
            <th>作成</th>
            <th>更新</th>
            <th>公開</th>
            <th>操作</th>
          </tr>
        </thead>
        <tbody>
          {#each entries as entry}
            <tr>
              <td>{entry.id}</td>
              <td class="date">{entry.date}</td>
              <td>
                {@render statusBadge(entry)}
              </td>
              <td>
                <div class="title">{entry.title}</div>
                <div class="path"><a href="/{entry.path}" target="_blank">/{entry.path}</a></div>
              </td>
              <td class="small">{entry.format}</td>
              <td class="time">{@render time(entry.created_at)}</td>
              <td class="time">{@render time(entry.modified_at)}</td>
              <td class="time">{@render time(entry.publish_at?.Time, entry.publish_at?.Valid)}</td>
              <td>
                <button class="edit-btn" onclick={() => onEdit(entry.id)}>編集</button>
              </td>
            </tr>
          {/each}
        </tbody>
      </table>
      {#if api.loading}
        <div class="overlay">
          <div class="loading-spinner"></div>
        </div>
      {/if}
    {/if}
  </div>
</div>

